import math

def logadd(values):
    m=max(values)
    return m+math.log(sum(math.exp(v-m) for v in values))

def eps_integer(z,q,T,delta=1e-9):
    out=[]
    for a in range(2,129):
        terms=[math.lgamma(a+1)-math.lgamma(i+1)-math.lgamma(a-i+1)+i*math.log(q)+(a-i)*math.log1p(-q)+(i*i-i)/(2*z*z) for i in range(a+1)]
        rdp=logadd(terms)/(a-1)
        eps=T*rdp-(math.log(delta)+math.log(a))/(a-1)+math.log((a-1)/a)
        out.append((eps,a))
    return min(out)
for z,q,T in [(0.6144,204800/69506000,2034),(2.048,204800/6950600,2006),(1.024,51200/1737650,2006),(1.024,102400/3475300,2006)]:
    print(dict(z=z,q=q,T=T,eps_order=eps_integer(z,q,T)))
